/**
 * 改造自 shadcn 原装 base-lyra textarea（https://ui.shadcn.com/r/styles/base-lyra/textarea.json，MIT）。
 * 与上游的差异：`rounded-none` 改成品牌层的圆角令牌 `rounded-control`（ADR 0024）。
 * 多行输入框与 Input 同属控件，圆角跟 Input 一致。缺省 `--brand-radius` 是 0，`rounded-control` 算出 0，与上游相同。
 * 此外只有格式化与一条 Biome 豁免注释，其余类名逐字保留。
 */
import { cn } from "cn";
import type * as React from "react";

function Textarea({ className, ...props }: React.ComponentProps<"textarea">) {
  return (
    // biome-ignore lint/correctness/noRestrictedElements: 这里就是注册表的 Textarea 组件本身，只能渲染原生元素。
    <textarea
      data-slot="textarea"
      className={cn(
        "flex field-sizing-content min-h-16 w-full rounded-control border border-input bg-transparent px-2.5 py-2 text-xs transition-colors outline-none placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-1 focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:bg-input/50 disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-1 aria-invalid:ring-destructive/20 md:text-xs dark:bg-input/30 dark:disabled:bg-input/80 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40",
        className,
      )}
      {...props}
    />
  );
}

export { Textarea };
